import { access } from "node:fs/promises";
import getPath from "./getPath.js";
const isFileExists = async (filepath, options = {}) => {
    const fullPath = getPath(filepath, options);
    if (!fullPath)
        return false;
    try {
        await access(fullPath);
        return true;
    }
    catch (err) {
        return false;
    }
};
export default isFileExists;
